%% public_key:pkix_path_validation/3 (plan 21 step LIB80D2): valid chains, every kind of failure, name constraints,
%% policies and policy mappings, options, path errors and verify funs that record what they are asked. The chains
%% were made once with OpenSSL (valid until 2036; one certificate expired in 2001).
-module(public_key_path).
-export([main/1]).

-include_lib("public_key/include/public_key.hrl").

main(_) ->
    Data = data(),
    C = fun(Name) -> proplists:get_value(Name, Data) end,
    Root = C(root),
    Cases = [
        {valid, [int, leaf], []},
        {name_constraints, [int, leafother], []},
        {policy_not_in_tree, [int, leafpol], []},
        {explicit_policy, [int, leafpol], [{explicit_policy, true}]},
        {explicit_policy_ok, [int, leaf], [{explicit_policy, true}]},
        {policy_set, [int, leaf], [{policy_set, ["1.2.3.7"]}, {explicit_policy, true}]},
        {policy_set_oid, [int, leaf], [{policy_set, [{1, 2, 3, 4}]}]},
        {inhibit_any, [int, leaf], [{inhibit_any_policy, true}]},
        {critical_extension, [int, leafcrit], []},
        {ext_key_usage, [int, leafeku], []},
        {expired, [int, leafold], []},
        {path_length, [int, intb, leafb], []},
        {mapped, [intmap, leafmapped], []},
        {mapped_explicit, [intmap, leafmapped], [{explicit_policy, true}]},
        {mapping_inhibited, [intmap, leafmapped], [{inhibit_policy_mapping, true}, {explicit_policy, true}]},
        {no_basic_constraints, [intnobc, leafnobc], []},
        {key_usage, [intku, leafku], []},
        {wrong_issuer, [leaf], []},
        {duplicate, [int, int, leaf], []},
        {max_path_length, [int, leaf], [{max_path_length, 0}]},
        {empty_chain, [], []}
    ],
    [
        begin
            Chain = [C(Name) || Name <- Names],
            io:format("~p~n  ~p~n  ~p~n", [
                Case, public_key:pkix_path_validation(Root, Chain, Options), traced(Root, Chain, Options)
            ])
        end
     || {Case, Names, Options} <- Cases
    ],
    Leaf = C(leaf),
    Tampered = tamper(Leaf),
    io:format("tampered ~p~n", [public_key:pkix_path_validation(Root, [C(int), Tampered], [])]),
    io:format("trusted forms ~p~n", [
        [
            element(1, public_key:pkix_path_validation(Trusted, [C(int), Leaf], []))
         || Trusted <- [Root, public_key:pkix_decode_cert(Root, otp), public_key:pkix_decode_cert(Root, plain)]
        ]
    ]),
    io:format("path error ~p~n", [public_key:pkix_path_validation(unknown_ca, [C(int), Leaf], [])]),
    Accept = {fun(_, _, State) -> {valid, State} end, []},
    io:format("path error accepted ~p~n", [
        public_key:pkix_path_validation(unknown_ca, [C(int), Leaf], [{verify_fun, Accept}])
    ]),
    io:format("path error failed ~p~n", [
        public_key:pkix_path_validation(
            unknown_ca, [C(int), Leaf], [{verify_fun, {fun(_, _, _) -> {fail, my_reason} end, []}}]
        )
    ]),
    Four = {
        fun(Otp, Der, Event, State) -> {valid, [{element(1, Otp), is_binary(Der), event(Event)} | State]} end, []
    },
    io:format("arity 4 ~p~n", [public_key:pkix_path_validation(Root, [C(int), Leaf], [{verify_fun, Four}])]),
    Fail = {
        fun
            (_, valid_peer, _) -> {fail, not_this_peer};
            (_, Event, State) -> {valid, [event(Event) | State]}
        end,
        []
    },
    io:format("fail peer ~p~n", [public_key:pkix_path_validation(Root, [C(int), Leaf], [{verify_fun, Fail}])]),
    io:format("public_key_path: ok~n").

%% The validation with a verify fun that accepts everything and sends the events it is given.
traced(Root, Chain, Options) ->
    Self = self(),
    Fun = fun
        (_, {bad_cert, _} = Reason, State) ->
            Self ! {event, Reason},
            {valid, State};
        (_, {extension, _} = Ext, State) ->
            Self ! {event, event(Ext)},
            {unknown, State};
        (_, Event, State) ->
            Self ! {event, Event},
            {valid, State}
    end,
    Result =
        case public_key:pkix_path_validation(Root, Chain, [{verify_fun, {Fun, []}} | Options]) of
            {ok, {_, Policies}} -> {ok, length(Policies)};
            Error -> Error
        end,
    {Result, events()}.

events() ->
    receive
        {event, Event} -> [Event | events()]
    after 0 -> []
    end.

event({extension, #'Extension'{extnID = Id, critical = Critical}}) -> {extension, Id, Critical};
event(Event) -> Event.

%% A certificate whose signature's last byte is changed.
tamper(Der) ->
    Size = byte_size(Der) - 1,
    <<Body:Size/binary, Last>> = Der,
    <<Body/binary, (Last bxor 1)>>.

